import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_ops_kernel(
    const float* original, 
    float* out, 
    const float* bias, 
    int batch_size, 
    int channels, 
    int depth, 
    int height, 
    int width) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = batch_size * channels * depth * height * width;
    if (idx >= total_size) return;

    int w = idx % width;
    int h = (idx / width) % height;
    int d = (idx / (width * height)) % depth;
    int c = (idx / (width * height * depth)) % channels;
    // int b = idx / (width * height * depth * channels); // not needed directly here

    float val = out[idx];
    float orig_val = original[idx];
    float bias_val = bias[c];

    // x = x + bias
    val += bias_val;
    // x = x + original_x
    val += orig_val;
    // x = x * original_x
    val *= orig_val;
    // x = x + original_x
    val += orig_val;

    out[idx] = val;
}

torch::Tensor fused_ops_cuda(
    torch::Tensor out,
    torch::Tensor original,
    torch::Tensor bias)
{
    int batch_size = out.size(0);
    int channels = out.size(1);
    int depth = out.size(2);
    int height = out.size(3);
    int width = out.size(4);

    int total_size = batch_size * channels * depth * height * width;

    const int block_size = 256;
    const int grid_size = (total_size + block_size - 1) / block_size;

    fused_ops_kernel<<<grid_size, block_size>>>(
        original.data_ptr<float>(),
        out.data_ptr<float>(),
        bias.data_ptr<float>(),
        batch_size,
        channels,
        depth,
        height,
        width
    );

    return out;
}
"""

fused_ops_cpp_source = r"""
torch::Tensor fused_ops_cuda(
    torch::Tensor out,
    torch::Tensor original,
    torch::Tensor bias);
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_ops_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a 3D transposed convolution, then fuses 
    the following operations into a single custom CUDA kernel:
      x = x + bias
      x = x + original_x
      x = x * original_x
      x = x + original_x
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding
        )
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        x = self.conv_transpose(x)
        original_x = x.clone().detach()
        x = fused_ops.fused_ops_cuda(x, original_x, self.bias)
        return x
